<script setup>
import {reactive,ref,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import AssessmentResult from '../../components/AssessmentResult.vue'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {createAssessmentPolicyApi,ASSESSMENT_EVIDENCE} from '../../services/assessment-policies.js'
import {createMonthlyAssessmentApi,defaultAssessmentMonth,assessmentSettlementRequest} from '../../services/monthly-assessment.js'
import {loadAdminMonthlyAssessment} from '../../services/monthly-assessment-pages.js'
import {createMonthlyAssessmentRecovery} from '../../services/monthly-assessment-recovery.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {imageRequestKey} from '../../services/private-images.js'
const state=reactive(initialDiagnosisState()),selected=ref(null),month=ref(defaultAssessmentMonth()),merchantPage=ref(1),detailId=ref(0),factPage=ref(1),confirmation=ref(null),receipt=ref(null)
const api=createMonthlyAssessmentApi(),merchantsApi=createAssessmentPolicyApi(),allowed=()=>operatorSession.canAssessment,blocked=()=>state.busy||state.retry||state.kind==='storage',recovery=createMonthlyAssessmentRecovery({actor:()=>operatorSession.actorId})
const flow=createAsyncDiagnosisFlow({state,token:operatorToken,allowed,scope:()=>`assessment-month:${operatorSession.actorId}`,recovery,newKey:imageRequestKey,load:(t,p)=>loadAdminMonthlyAssessment({api,merchantsApi,token:t,page:p,merchantPage:merchantPage.value,merchant:selected.value,month:month.value,detailId:detailId.value,factPage:factPage.value}),write:api.write,onWritten:value=>{receipt.value=value;month.value=value.period_month;selected.value=value.policy?.merchant||{id:value.merchant_id,name:`门店 ${value.merchant_id}`,address:''};detailId.value=value.id;factPage.value=1},confirm:action=>new Promise(resolve=>{const q=confirmation.value;uni.showModal({title:action==='discard-local'?'核对后清理本机请求':'确认月度结算',content:action==='discard-local'?'请核对服务器历史和当前版本。只清理本机原请求，不删除已冻结的结果或重新提交。':q?`${q.name}\n北京时间 ${q.body.period_month}\n当前修订 ${q.body.expected_revision}，本次生成新修订。\n固定权重40%／40%／20%。${q.unknown?'没有整月政策，将生成未知结果。':'依据已读取的来源政策计算。'}${q.policy?'\n来源：'+q.policy.source_note+'\n目标：拉新 '+q.policy.acquisition_target+'／券 '+q.policy.coupon_target+'；必需证据 '+q.policy.process_requirements.length+' 项、等级 '+q.policy.grade_thresholds.length+' 档':''}\n后续全退需回原使用月复算，旧快照仍保留。`:'请重新读取月份后确认。',success:r=>resolve(r.confirm&&Boolean(q||action==='discard-local')),fail:()=>resolve(false)})})})
let visible=false
function reset(){flow.reset();selected.value=null;month.value=defaultAssessmentMonth();detailId.value=0;factPage.value=1;merchantPage.value=1;confirmation.value=null;receipt.value=null}
function choose(m){if(blocked())return;selected.value=JSON.parse(JSON.stringify(m));detailId.value=0;factPage.value=1;flow.load()}
function refresh(){if(state.busy)return;detailId.value=0;factPage.value=1;flow.load()}
function sourceNext(d){if(blocked())return;merchantPage.value+=d;flow.load(state.page)}
function show(r){if(blocked())return;detailId.value=r.id;factPage.value=1;flow.load(state.page)}
function factNext(d){if(blocked())return;factPage.value+=d;flow.load(state.page)}
function settle(){if(blocked())return;try{const body=assessmentSettlementRequest(state.data?.context,selected.value?.id,month.value);confirmation.value={name:state.data.context.merchant.name,unknown:state.data.context.policy===null,policy:JSON.parse(JSON.stringify(state.data.context.policy)),body:JSON.parse(JSON.stringify(body))};flow.save('settle',0,body)}catch(e){state.message=e.message}}
function original(){if(!state.retry||!state.data)return '';try{const p=recovery.read().pending;return p?`待恢复原请求：门店 ${p.body.merchant_id}，${p.body.period_month}，期望修订 ${p.body.expected_revision}`:''}catch{return '本机原请求需要核对'}}
function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
watch(()=>[operatorSession.accessToken,allowed()],()=>{reset();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k)){receipt.value=null;confirmation.value=null}})
onShow(()=>{visible=true;if(operatorToken()&&allowed())flow.load()});onHide(()=>{visible=false;reset()});onUnload(()=>{visible=false;reset()})
</script>
<template><view class="reservation-page">
 <text class="reservation-title">门店月度结算</text><text>北京时间自然月，次月起结算。每次复算生成新修订，历史结果保留。</text><button v-if="!operatorToken()" @tap="login">运营登录</button><text v-else-if="!allowed()">当前账号没有考核权限。</text><template v-else>
 <view v-if="state.busy" class="reservation-panel" aria-busy="true"><text role="status">正在读取或提交月结记录…</text></view><text v-if="state.message" role="status">{{state.message}}</text><text v-if="state.retry">{{original()}}</text><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原月结请求</button><button v-if="state.kind==='storage'" :disabled="state.busy" @tap="flow.discardLocal">核对服务器并清理本机请求</button><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button>
 <input v-model="month" maxlength="7" :disabled="blocked()" placeholder="结算月份 YYYY-MM"/><button :disabled="state.busy" @tap="refresh">读取所选月份与服务器历史</button>
 <template v-if="state.data"><view class="reservation-panel"><text class="reservation-heading">选择有效门店</text><text v-if="!state.data.merchants.items.length">没有有效门店；已有成功请求仍可按原键恢复。</text><view v-for="m in state.data.merchants.items" :key="m.id"><text>{{m.name}} · {{m.address}}</text><button :disabled="blocked()" @tap="choose(m)">读取此门店</button></view><button v-if="merchantPage>1" :disabled="blocked()" @tap="sourceNext(-1)">上一页门店</button><button v-if="merchantPage*20<state.data.merchants.total" :disabled="blocked()" @tap="sourceNext(1)">下一页门店</button></view>
 <view v-if="state.data.context" class="reservation-panel"><text class="reservation-heading">{{state.data.context.merchant.name}} · {{state.data.context.period_month}}</text><text>服务器当前修订 {{state.data.context.revision}}</text><text v-if="state.data.context.state==='MONTH_OPEN'">月份尚未结束，不能结算。</text><text v-if="!state.data.context.policy">没有可证明覆盖整月的政策，结果将显示未知。</text><template v-else><text>政策来源：{{state.data.context.policy.source_note}}</text><text>拉新目标 {{state.data.context.policy.acquisition_target}} · 券目标 {{state.data.context.policy.coupon_target}}</text><text v-for="e in state.data.context.policy.process_requirements" :key="e">{{ASSESSMENT_EVIDENCE[e]}}</text><text v-for="g in state.data.context.policy.grade_thresholds" :key="g.code">{{g.label}}：至少 {{g.min_score}} 分</text></template><button :disabled="blocked()||!state.data.context.can_settle||state.data.context.period_month!==month" @tap="settle">确认并生成新修订</button></view><text v-if="state.data.selection_error">原门店当前不可用；可查看历史或重试已保存的原请求。</text>
 <AssessmentResult v-if="state.data.context&&state.data.context.latest&&!state.data.detail" :value="state.data.context.latest"/><text class="reservation-heading">{{selected?'所选门店月份的历史修订':'全部历史修订（先选门店再结算）'}}</text><text v-if="!state.data.items.length">没有冻结结果，不显示默认0分。</text><view v-for="r in state.data.items" :key="r.id" class="reservation-panel"><text>门店 {{r.merchant_id}} · {{r.period_month}} · 修订 {{r.revision}} · {{r.summary.state==='CALCULATED'?r.summary.total_score+' 分':'未知'}}</text><button :disabled="blocked()" @tap="show(r)">查看本修订及依据</button></view><button v-if="state.page>1" :disabled="blocked()" @tap="flow.load(state.page-1)">上一页修订</button><button v-if="state.page*20<state.data.total" :disabled="blocked()" @tap="flow.load(state.page+1)">下一页修订</button>
 <AssessmentResult v-if="state.data.detail" :value="state.data.detail" :facts="state.data.facts"/><button v-if="state.data.facts&&factPage>1" :disabled="blocked()" @tap="factNext(-1)">上一页依据</button><button v-if="state.data.facts&&factPage*20<state.data.facts.total" :disabled="blocked()" @tap="factNext(1)">下一页依据</button><AssessmentResult v-if="receipt&&!state.data.detail&&!(state.data.context&&state.data.context.latest)" :value="receipt"/>
 </template></template><button @tap="uni.navigateTo({url:'/pages/operator/assessment-policies'})">考核政策配置</button><button @tap="uni.navigateTo({url:'/pages/operator/review'})">运营工作区</button>
</view></template>
